using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "SearingRitualAction", menuName = "Data/Battle/Battle Actions/Sothis/SearingRitual Action")]
public class SearingRitualAction : BattleAction
{
	[Header("Searing Ritual")]
	[SerializeField]
	private ReliefDefaultEffectAction reliefDefaultEffectAction;

	[SerializeField]
	private DefaultEffectAction chantingAction;

	[SerializeField]
	private Effect chantingEffect;

	public ReliefDefaultEffectAction ReliefDefaultEffectAction => reliefDefaultEffectAction;

	public DefaultEffectAction ChantingAction => chantingAction;

	public int GetReliefAmount()
	{
		return ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsEffectActiveGetAmount(chantingEffect, activateFeedback: false) + 1;
	}

	public override void AreaCastTarget(List<GameObject> targets, GameObject source)
	{
		reliefDefaultEffectAction.AreaCastTargetAmount(targets, GetReliefAmount(), source);
		chantingAction.CastTargetAmount(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject, 1, source);
	}
}
